Building working views first: entities merged by LEI, QA records excluded, RESEARCH country taking precedence.

```sql
CREATE OR REPLACE VIEW ek AS SELECT entity_id, coalesce(nullif(lei,''),entity_id) k, name, country, entity_type, nullif(parent_id,'') parent_id, source_system FROM entities WHERE source_system<>'QA';
CREATE OR REPLACE VIEW ent AS SELECT k, coalesce(max(name) filter(where source_system='RATINGS'), max(name)) name, coalesce(max(country) filter(where source_system='RESEARCH'), max(country)) country, max(entity_type) entity_type, coalesce(max(parent_id) filter(where source_system='RATINGS'), max(parent_id)) pid, coalesce(min(entity_id) filter(where source_system='RATINGS'), min(entity_id)) rep FROM ek GROUP BY k;
CREATE OR REPLACE VIEW par AS SELECT e.k, e.rep, e.name, e.country, e.entity_type, p.k pk FROM ent e LEFT JOIN ek p ON p.entity_id=e.pid;
CREATE OR REPLACE VIEW grp AS WITH RECURSIVE r(k, root, depth) AS (SELECT k,k,0 FROM par WHERE pk IS NULL UNION ALL SELECT p.k, r.root, r.depth+1 FROM par p JOIN r ON p.pk=r.k) SELECT * FROM r;
CREATE OR REPLACE VIEW act AS SELECT a.*, ek.k FROM rating_actions a JOIN ek ON ek.entity_id=a.rated_id;
CREATE OR REPLACE VIEW st AS SELECT * FROM (SELECT k, rating_type, ccy_basis, date, action, rating, outlook, watch, row_number() over (partition by k,rating_type,ccy_basis order by date desc, action_id desc) rn FROM act WHERE date<='2026-10-01' AND rating_type IN ('LTIDR','STIDR')) WHERE rn=1;
SELECT (SELECT count(*) FROM ent) n_ent, (SELECT count(*) FROM grp) n_grp, (SELECT count(*) FROM par) n_par;
```

```sql
SELECT g.root, r.rep, r.name, count(*) n, max(g.depth) maxd, count(*) filter(where g.depth=3) d3 FROM grp g JOIN ent r ON r.k=g.root GROUP BY ALL HAVING count(*)>1 ORDER BY n DESC;
```

```sql
SELECT 'LU' x, string_agg(rep,',') FROM ent WHERE country='LU'
UNION ALL SELECT 'default_ever', string_agg(DISTINCT e.rep,',') FROM act a JOIN ent e ON e.k=a.k WHERE a.rating_type IN ('LTIDR','STIDR') AND a.rating IN ('RD','D')
UNION ALL SELECT 'default_1Oct', string_agg(DISTINCT e.rep,',') FROM st s JOIN ent e ON e.k=s.k WHERE s.rating IN ('RD','D')
UNION ALL SELECT 'issuers_rated', count(DISTINCT k)::varchar FROM st WHERE rating_type='LTIDR' AND rating<>'WD'
UNION ALL SELECT 'GB_rated', count(DISTINCT s.k)::varchar FROM st s JOIN ent e ON e.k=s.k WHERE rating_type='LTIDR' AND rating<>'WD' AND e.country='GB'
UNION ALL SELECT 'RWN', string_agg(DISTINCT e.rep,',') FROM st s JOIN ent e ON e.k=s.k WHERE rating_type='LTIDR' AND watch='RWN' AND rating<>'WD'
UNION ALL SELECT 'NEG', string_agg(DISTINCT e.rep,',') FROM st s JOIN ent e ON e.k=s.k WHERE rating_type='LTIDR' AND outlook='NEG' AND rating<>'WD'
UNION ALL SELECT 'lost', string_agg(DISTINCT e.rep,',') FROM (SELECT DISTINCT k FROM act WHERE rating_type='LTIDR' AND action<>'WD') h JOIN ent e ON e.k=h.k WHERE NOT EXISTS (SELECT 1 FROM st s WHERE s.k=h.k AND s.rating_type='LTIDR' AND s.rating<>'WD')
UNION ALL SELECT 'DG2026', string_agg(DISTINCT e.rep,',') FROM act a JOIN ent e ON e.k=a.k WHERE a.rating_type='LTIDR' AND a.action='DG' AND a.date BETWEEN '2026-01-01' AND '2026-12-31'
UNION ALL SELECT 'future', count(*)::varchar FROM rating_actions WHERE date>'2026-10-01';
```

Aliasing `name` without `AS` caused the parse error, so I'm rebuilding the views with explicit aliases.

```sql
CREATE OR REPLACE VIEW ek AS SELECT entity_id, coalesce(nullif(lei,''),entity_id) AS k, name AS nm, country, entity_type, nullif(parent_id,'') AS parent_id, source_system FROM entities WHERE source_system<>'QA';
CREATE OR REPLACE VIEW ent AS SELECT k, coalesce(max(nm) filter(where source_system='RATINGS'), max(nm)) AS nm, coalesce(max(country) filter(where source_system='RESEARCH'), max(country)) AS country, max(entity_type) AS entity_type, coalesce(max(parent_id) filter(where source_system='RATINGS'), max(parent_id)) AS pid, coalesce(min(entity_id) filter(where source_system='RATINGS'), min(entity_id)) AS rep FROM ek GROUP BY k;
CREATE OR REPLACE VIEW par AS SELECT e.k, e.rep, e.nm, e.country, e.entity_type, p.k AS pk FROM ent e LEFT JOIN ek p ON p.entity_id=e.pid;
CREATE OR REPLACE VIEW grp AS WITH RECURSIVE r(k, root, depth) AS (SELECT k,k,0 FROM par WHERE pk IS NULL UNION ALL SELECT p.k, r.root, r.depth+1 FROM par p JOIN r ON p.pk=r.k) SELECT * FROM r;
CREATE OR REPLACE VIEW act AS SELECT a.*, ek.k FROM rating_actions a JOIN ek ON ek.entity_id=a.rated_id;
CREATE OR REPLACE VIEW st AS SELECT * FROM (SELECT k, rating_type, ccy_basis, date, action, rating, outlook, watch, row_number() over (partition by k,rating_type,ccy_basis order by date desc, action_id desc) AS rn FROM act WHERE date<='2026-10-01' AND rating_type IN ('LTIDR','STIDR')) WHERE rn=1;
SELECT (SELECT count(*) FROM ent) n_ent, (SELECT count(*) FROM grp) n_grp, (SELECT count(*) FROM par) n_par;
```

